#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

# why "..." explains, in plain words, what a stage is for.
why() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
# see "..." tells the human what the screen should look like when it worked.
see() { printf '  %s✓ You should now see:%s %s\n' "$GREEN" "$RESET" "$1"; }
# gap prints a blank line so the steps are easy to tell apart.
gap() { printf '\n'; }

run_wizard() {

TOTAL_STAGES=9

banner "Set up email for Cadence Notifications"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "What we are about to do"
say "Two websites are involved. You don't need to know either of them."
gap
say "${BOLD}Postmark${RESET} is a service that delivers email. Think of it as the post office."
say "${BOLD}Knock${RESET} is the service Cadence already uses for Notifications. It decides"
say "who gets which Notification. To send one as an email, it hands the email"
say "to Postmark."
gap
say "So the job is: open a Postmark account, then give Knock the password"
say "(called an 'API token') that lets it send email through that account."
gap
say "It takes about 10 minutes. Nothing costs money and no card is needed."
say "Each screen here gives you one small job. Do it in the browser, come"
say "back to this window, and press Enter."
gap
note "Stuck or made a mistake? Press Ctrl-C to stop. You can run this again"
note "from the start at any time; repeating a step does no harm."
pause "Press Enter to begin"

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Postmark: get into your account"
why "Why: we need a Postmark account to send email from."
gap
if confirm "Do you (or Cadence) already have a Postmark account?"; then
  gap
  open_url "https://account.postmarkapp.com/login"
  step "1. A browser tab has opened on Postmark's login page."
  step "2. Type your email and password and log in."
else
  gap
  note "No problem, we'll make one. (Not sure? Answer no; if Postmark says the"
  note "email is already in use, use 'Forgot password' on its login page.)"
  gap
  open_url "https://account.postmarkapp.com/sign_up"
  step "1. A browser tab has opened on Postmark's sign-up page."
  step "2. Fill in the form. Use your WORK email address (one on your own"
  step "   company domain, not Gmail or Outlook). This matters in a later step."
  step "3. Postmark sends you an email. Open it and click the link inside to"
  step "   confirm your address."
  step "4. If it asks questions about how you'll use Postmark, any answer is fine."
  gap
  note "Postmark may say your account is 'pending approval' or in 'test mode'."
  note "Ignore that. It is enough for what we need, and you should NOT click"
  note "'Request approval'."
fi
gap
see "the Postmark dashboard, with a menu containing 'Servers'."
pause "Press Enter once you are logged in to Postmark"

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Postmark: prove you own the 'from' address"
why "Why: every email needs a 'from' address. Postmark refuses to send from"
why "an address until its owner has clicked a confirmation link. Postmark"
why "calls a confirmed address a 'Sender Signature'."
gap
open_url "https://account.postmarkapp.com/signature_domains"
step "1. A tab has opened on the 'Sender Signatures' page."
step "2. Look at the list. If your work email is there on its own row, with"
step "   no 'Unconfirmed' marker, you are done with this screen."
step "3. If not: click the blue 'Add Signature' button (on an empty page it"
step "   may be labelled 'Add Domain or Signature')."
step "4. Full name: Cadence.   From email: your work email address."
step "5. Save. Postmark emails that address. Open the email and click the"
step "   confirmation button in it."
step "6. Go back to the Sender Signatures tab and refresh the page."
gap
warn "It must be an address whose inbox you can open right now, on your own"
warn "domain. A new Postmark account can only deliver to addresses on the same"
warn "domain as the sender, so we'll send the test email to this same address."
gap
note "You will see red 'DKIM Not Verified' and 'Return-Path Not Verified'"
note "labels beside your domain name. Ignore them: they are about verifying"
note "the whole domain, which we don't need. Don't click 'DNS Settings'."
gap
see "your work email on its own row under your domain, with no"
say "  'Unconfirmed' or 'Resend confirmation' marker beside it."
pause "Press Enter once your address shows as verified"

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Postmark: copy the server API token"
why "Why: the 'Server API token' is the password Knock will use to send"
why "email through your Postmark account. It is a long string of letters,"
why "numbers and dashes."
gap
open_url "https://account.postmarkapp.com/servers"
step "1. A tab has opened on the 'Servers' page. A 'server' in Postmark is"
step "   just a folder for one app's email, not a real machine."
step "2. Click the server in the list. A new account has exactly one, called"
step "   'My First Server'. (None there? Click 'Create Server', name it"
step "   'Cadence Development', and open it.)"
step "3. Inside the server, click the tab named 'API Tokens'."
step "4. Click the copy icon next to the token under 'Server API tokens'."
gap
warn "Copy the SERVER token, inside the server. There is also an 'Account API"
warn "token' in the account menu. That is a different thing and will not work."
gap
note "Now leave it alone: don't copy anything else until the next-but-one"
note "screen, or you'll lose it from your clipboard. (If you do, come back to"
note "this Postmark tab and copy it again. It doesn't change.)"
note "The token is deliberately not saved on this computer."
pause "Press Enter once the token is copied"

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Knock: create the email channel"
why "Why: in Knock, a 'channel' is one way of reaching people. Cadence has"
why "one already (the in-app Notification Feed). We are adding a second: email."
gap
open_url "https://dashboard.knock.app"
step "1. A tab has opened on the Knock dashboard. Log in if it asks."
step "2. Open Settings (bottom-left of the page), then click"
step "   'Channels and sources'."
step "3. You'll see a list that already includes 'Notification Feed'."
step "   Click the button to create a channel ('Create channel')."
step "4. Pick the type 'Email', then pick the provider 'Postmark'."
step "5. It asks for a name and a key. Type exactly:"
gap
say "        Name:  ${BOLD}Postmark${RESET}"
say "        Key:   ${BOLD}postmark${RESET}  (all lowercase)"
gap
step "6. Leave the description empty and click Create."
gap
warn "Get the key right before you click Create: it can never be changed."
warn "Do NOT pick 'Knock email' from the existing list. That is a different,"
warn "built-in test channel. We are making a new one."
gap
see "a page for the new 'Postmark' channel, with a section called"
say "  'Environment configurations' listing Development and Production."
pause "Press Enter once the Postmark channel exists"

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Knock: connect the channel to Postmark"
why "Why: the channel exists but doesn't know your Postmark account yet."
why "We connect it for Development only, the safe practice area. Production"
why "(the real thing) stays untouched."
gap
step "1. Stay on the Postmark channel's page in Knock."
step "2. Under 'Environment configurations', find the ${BOLD}Development${RESET} row and"
step "   click it to open its settings (the button may say 'Manage configuration')."
step "3. Fill in two boxes:"
gap
say "        API key:             paste the Postmark token (Cmd-V / Ctrl-V)"
say "        From email address:  the work email you verified in Postmark"
gap
step "4. Open the 'Advanced' section, find 'From name' (under Overrides)"
step "   and type: Cadence"
step "5. Still in Advanced, check these and leave them as they are:"
gap
say "        Sandbox mode:   OFF   (if it is on, no email is ever sent)"
say "        Open tracking:  OFF"
say "        Link tracking:  OFF"
gap
step "6. Click 'Save changes'."
gap
warn "Only touch the Development row. Do not open or fill in Production."
gap
see "the Development row marked as configured, with no error message."
pause "Press Enter once the Development settings are saved"

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Knock: copy the channel ID"
why "Why: Cadence's code points at the channel by its ID, so we save the ID"
why "on this computer. It is not a secret."
gap
step "1. Stay on the Postmark channel's page in Knock."
step "2. Near the top, by the channel's name, find the channel ID. It looks"
step "   like this:  3f2b8c1e-9a4d-4e7b-b1c2-5d6e7f8a9b0c"
step "   (five groups of letters and numbers joined by dashes)."
step "3. Click it, or the copy icon beside it, to copy it."
step "4. Come back here, paste it below (Cmd-V / Ctrl-V) and press Enter."
gap
note "This is the ID, not the key. The key is the word 'postmark'."
gap
ask KNOCK_EMAIL_CHANNEL_ID "Paste the channel ID:"
KNOCK_EMAIL_CHANNEL_ID=$(printf '%s' "$KNOCK_EMAIL_CHANNEL_ID" | tr -d '[:space:]')
if [[ ! "$KNOCK_EMAIL_CHANNEL_ID" =~ ^[0-9a-fA-F]{8}(-[0-9a-fA-F]{4}){3}-[0-9a-fA-F]{12}$ ]]; then
  gap
  warn "That isn't a channel ID. (${#KNOCK_EMAIL_CHANNEL_ID} characters; an ID has 36.)"
  warn "You may have pasted the Postmark token or the key instead."
  warn "Nothing was saved. Run the wizard again; you can press Enter straight"
  warn "through the screens you've already done."
  exit 1
fi
if [[ "$KNOCK_EMAIL_CHANNEL_ID" == "$(_existing KNOCK_FEED_CHANNEL_ID || true)" ]]; then
  gap
  warn "That is the ID of the 'Notification Feed' channel, not 'Postmark'."
  warn "Nothing was saved. Run the wizard again, open the channel named"
  warn "'Postmark' and copy the ID from that page."
  exit 1
fi
gap
write_env KNOCK_EMAIL_CHANNEL_ID "$KNOCK_EMAIL_CHANNEL_ID"
pause

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "Check: three things to confirm"
say "Look back at your two browser tabs and check each of these is true."
gap
ok=1
confirm "Postmark: your work email is listed as a verified Sender Signature?" || ok=0
confirm "Knock: a channel named 'Postmark' exists?" || ok=0
confirm "Knock: its Development settings are saved, with Sandbox mode OFF?" || ok=0
gap
if (( ok )); then
  printf '  %s✓ All set.%s\n' "$GREEN" "$RESET"
else
  warn "Something isn't done yet. That's fine: run the wizard again and redo"
  warn "just that screen, or tell Claude which one you couldn't do."
fi
pause

# ── 9 ─────────────────────────────────────────────────────────────────────
stage "Last step: tell Claude"
say "Your part is done. Go back to Claude and type:"
gap
say "        ${BOLD}done${RESET}"
gap
say "Claude will then send one test Notification email to your work address."
say "Keep that inbox open: the email should arrive within a minute."
say "Tell Claude whether it arrived."
pause "Press Enter to finish"

finish
}

run_wizard "$@"; exit
